     3	/**
     4	 * Computes the Luhn check digit over the digits of an owner's {@code customerCode}.
     5	 *
     6	 * <p>The customer code contains non-digit characters (e.g. {@code 'NSW-1A2B3C4D'}); only the digit
     7	 * characters take part in the Luhn calculation, processed right-to-left with every second digit
     8	 * doubled and any result above nine reduced by nine. The check digit is the amount that must be
     9	 * added to the running sum to reach the next multiple of ten.
    10	 *
    11	 * <p>Kept as a standalone helper rather than a method on {@link OwnerMapper}: a single-argument
    12	 * method declared on a MapStruct mapper would be picked up as an implicit conversion and applied to
    13	 * matching property mappings.
    14	 */
    15	public final class CustomerCodeCheckDigit {
    16	
    17	    private CustomerCodeCheckDigit() {
    18	    }
    19	
    20	    /**
    21	     * Returns the Luhn check digit (0-9) over the digit characters of {@code customerCode}, or
    22	     * {@code 0} when the value is {@code null} or contains no digits.
    23	     */
    24	    public static int of(String customerCode) {
    25	        if (customerCode == null) {
    26	            return 0;
    27	        }
    28	        int sum = 0;
    29	        boolean doubleDigit = true;
    30	        for (int i = customerCode.length() - 1; i >= 0; i--) {
    31	            char c = customerCode.charAt(i);
    32	            if (c < '0' || c > '9') {
    33	                continue;
    34	            }
    35	            int d = c - '0';
    36	            if (doubleDigit) {
    37	                d *= 2;
    38	                if (d > 9) {
    39	                    d -= 9;
    40	                }
    41	            }
    42	            sum += d;
    43	            doubleDigit = !doubleDigit;
    44	        }
    45	        return (10 - (sum % 10)) % 10;
    46	    }
    47	}
