     3	import java.time.LocalDate;
     4	import java.time.Month;
     5	
     6	/**
     7	 * Derives fiscal-year values from a date, where the fiscal year starts on 1 July.
     8	 *
     9	 * <p>A date on or after 1 July belongs to the fiscal year that ends the following 30 June, so it is
    10	 * named by that ending calendar year; a date before 1 July belongs to the fiscal year ending in its
    11	 * own calendar year (e.g. 2026-07-01 and 2027-06-30 both fall in fiscal year 2027, while 2026-06-30
    12	 * falls in fiscal year 2026).
    13	 *
    14	 * <p>Kept as a standalone helper rather than a method on {@link OwnerMapper}: a single-argument
    15	 * method declared on a MapStruct mapper would be picked up as an implicit conversion and applied to
    16	 * every matching property mapping.
    17	 */
    18	public final class FiscalYear {
    19	
    20	    private FiscalYear() {
    21	    }
    22	
    23	    /**
    24	     * Returns the fiscal year (the ending calendar year) the given date falls in.
    25	     */
    26	    public static int yearOf(LocalDate date) {
    27	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
    28	    }
    29	
    30	    /**
    31	     * Returns the fiscal year of {@code date} formatted as {@code "FY<YY>"} where {@code YY} is the
    32	     * last two digits of the fiscal year (e.g. {@code "FY27"}), or {@code null} when {@code date} is
    33	     * absent so no fiscal year can be derived.
    34	     */
    35	    public static String of(LocalDate date) {
    36	        if (date == null) {
    37	            return null;
    38	        }
    39	        return String.format("FY%02d", yearOf(date) % 100);
    40	    }
    41	}
