     5	
     6	/**
     7	 * Formats a stored E.164 telephone number for human display.
     8	 *
     9	 * <p>The E.164 value ('+' followed by country code and national digits) is rendered as the country
    10	 * code, a single space, then the national digits grouped in threes from the left, e.g.
    11	 * {@code '+61412345678'} becomes {@code '+61 412 345 678'}. The raw {@code telephone} is left in
    12	 * E.164 form; this is a read-only display companion.
    13	 *
    14	 * <p>Kept as a standalone helper rather than a method on {@link OwnerMapper}: a single-argument
    15	 * {@code String}-to-{@code String} method declared on a MapStruct mapper would be picked up as an
    16	 * implicit conversion and applied to every String property mapping.
    17	 */
    18	public final class TelephoneDisplay {
    19	
    20	    /**
    21	     * Known E.164 country codes, matched longest-first so {@code '61'} wins over {@code '1'}. A
    22	     * number that starts with no known code is grouped as a whole after the {@code '+'}.
    23	     */
    24	    private static final Set<String> COUNTRY_CODES = Set.of("1", "61");
    25	
    26	    private TelephoneDisplay() {
    27	    }
    28	
    29	    /**
    30	     * Formats {@code telephone} (an E.164 string such as {@code '+61412345678'}) as
    31	     * {@code '+<countryCode> <national digits grouped in threes>'}. A {@code null} or blank value,
    32	     * or one carrying no digits, is returned unchanged.
    33	     */
    34	    public static String of(String telephone) {
    35	        if (telephone == null || telephone.isBlank()) {
    36	            return telephone;
    37	        }
    38	        String digits = telephone.replaceAll("\\D", "");
    39	        if (digits.isEmpty()) {
    40	            return telephone;
    41	        }
    42	        String countryCode = COUNTRY_CODES.stream()
    43	            .filter(digits::startsWith)
    44	            .max(Comparator.comparingInt(String::length))
    45	            .orElse("");
    46	        String national = digits.substring(countryCode.length());
    47	        StringBuilder sb = new StringBuilder("+").append(countryCode);
    48	        boolean needsSpace = !countryCode.isEmpty();
    49	        for (int i = 0; i < national.length(); i += 3) {
    50	            if (needsSpace) {
    51	                sb.append(' ');
    52	            }
    53	            needsSpace = true;
    54	            sb.append(national, i, Math.min(i + 3, national.length()));
    55	        }
    56	        return sb.toString();
    57	    }
    58	}
