    14	 * {@code String}-to-{@code String} method declared on a MapStruct mapper would be picked up as an
    15	 * implicit conversion and applied to every String property mapping.
    16	 */
    17	public final class OwnerLocality {
    18	
    19	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
    20	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
    21	        "NSW", new int[] {2000, 2099},
    22	        "VIC", new int[] {3000, 3099},
    23	        "QLD", new int[] {4000, 4099});
    24	
    25	    /** Region -&gt; IANA timezone name. */
    26	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
    27	        "NSW", "Australia/Sydney",
    28	        "VIC", "Australia/Melbourne",
    29	        "QLD", "Australia/Brisbane");
    30	
    31	    private OwnerLocality() {
    32	    }
    33	
    34	    /**
    35	     * Returns the canonical region, preferring the {@code postcode}: a postcode in a known region
    36	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) selects that region. When the postcode is
    37	     * absent, malformed, or in no known range, falls back to the city-to-region table via
    38	     * {@link #derive(String)}.
    39	     */
    40	    public static String derive(String city, String postcode) {
    41	        String fromPostcode = regionForPostcode(postcode);
    42	        if (fromPostcode != null) {
    43	            return fromPostcode;
    44	        }
    45	        return derive(city);
    46	    }
    47	
    48	    /**
    49	     * Returns the canonical region for {@code city} (Sydney-&gt;NSW, Melbourne-&gt;VIC,
    50	     * Brisbane-&gt;QLD), or {@code "UNKNOWN"} when the city is not in the table.
    51	     */
    52	    public static String derive(String city) {
    53	        if (city == null) {
    54	            return "UNKNOWN";
    55	        }
    56	        switch (city) {
    57	            case "Sydney":
    58	                return "NSW";
    59	            case "Melbourne":
    60	                return "VIC";
    61	            case "Brisbane":
    62	                return "QLD";
    63	            default:
    64	                return "UNKNOWN";
    65	        }
    66	    }
    67	
    68	    /**
    69	     * Returns the region an owner's identity resolves to by reading it back off the
    70	     * {@code customerCode}, which is formatted {@code '<REGION>-<HASH8>'}: the portion before the
    71	     * first {@code '-'}. The locality therefore shares the single region-and-hash identity assigned
    72	     * at creation instead of being recomputed from the city and postcode. Returns {@code "UNKNOWN"}
    73	     * when the customer code is absent, blank, or carries no region segment.
    74	     */
    75	    public static String fromCustomerCode(String customerCode) {
    76	        if (customerCode == null || customerCode.isBlank()) {
