    82	    }
    83	
    84	    /**
    85	     * Returns the IANA timezone name for {@code region} via the fixed region-to-timezone table
    86	     * (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane), or
    87	     * {@code null} when the region is absent or not in the table.
    88	     */
    89	    public static String timezoneForRegion(String region) {
    90	        return region == null ? null : REGION_TIMEZONE.get(region);
    91	    }
    92	
    93	    /** Region for a 4-digit {@code postcode} in a known range, or {@code null} otherwise. */
    94	    private static String regionForPostcode(String postcode) {
    95	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
    96	            return null;
    97	        }
    98	        int value = Integer.parseInt(postcode);
    99	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
   100	            int[] range = entry.getValue();
   101	            if (value >= range[0] && value <= range[1]) {
   102	                return entry.getKey();
   103	            }
   104	        }
   105	        return null;
   106	    }
   107	}
