     6	/**
     7	 * Derives an owner's age band from a birth date measured against the registration date.
     8	 *
     9	 * <p>The age in whole years is computed between {@code birthDate} and {@code registrationDate};
    10	 * that age selects the band: {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64
    11	 * inclusive, and {@code "SENIOR"} at 65 or over. When no birth date is present there is no band and
    12	 * {@code null} is returned so the field is omitted from the response.
    13	 *
    14	 * <p>Kept as a standalone helper rather than a method on {@link OwnerMapper}: a single-argument
    15	 * method declared on a MapStruct mapper would be picked up as an implicit conversion and applied to
    16	 * every matching property mapping.
    17	 */
    18	public final class AgeBand {
    19	
    20	    private AgeBand() {
    21	    }
    22	
    23	    /**
    24	     * Returns the age band for {@code birthDate} measured against {@code registrationDate}, or
    25	     * {@code null} when either date is absent so no band can be derived.
    26	     */
    27	    public static String of(LocalDate birthDate, LocalDate registrationDate) {
    28	        if (birthDate == null || registrationDate == null) {
    29	            return null;
    30	        }
    31	        long age = ChronoUnit.YEARS.between(birthDate, registrationDate);
    32	        if (age < 18) {
    33	            return "MINOR";
    34	        }
    35	        if (age < 65) {
    36	            return "ADULT";
    37	        }
    38	        return "SENIOR";
    39	    }
    40	}
