    19	import tools.jackson.databind.ObjectMapper;
    20	import tools.jackson.databind.json.JsonMapper;
    21	
    22	/**
    23	 * Immutable structured audit event emitted on a successful owner create, alongside the
    24	 * human-readable audit line. It is rendered to a stable JSON object
    25	 * {@code {seq, ownerId, customerCode, membershipLevel, event}} - the component declaration order is
    26	 * the serialized field order - and published to the dedicated {@code AUDIT} logger.
    27	 *
    28	 * <p>{@code seq} is a monotonically increasing sequence number assigned across creates, so events
    29	 * carry a total order independent of the owner id.
    30	 *
    31	 * <p>{@code customerCode} carries the owner's <em>current primary identifier</em>. Today that is the
    32	 * owner's {@code customerCode}; when the customer code is later unified into the member id, the
    33	 * caller supplies the member id here instead and the event follows automatically, without this
    34	 * type changing.
    35	 *
    36	 * <p>The record is immutable: its components are set once at construction and never mutated, so a
    37	 * published event is a faithful, tamper-proof snapshot of the create.
    38	 */
    39	public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, Integer membershipLevel,
    40	                                String event) {
    41	
    42	    /** The fixed {@code event} discriminator carried by every owner-created event. */
    43	    public static final String EVENT_TYPE = "OWNER_CREATED";
    44	
    45	    private static final ObjectMapper MAPPER = JsonMapper.builder().build();
    46	
    47	    /**
    48	     * Creates an {@code OWNER_CREATED} event with the given sequence number, owner id, primary
    49	     * identifier and membership level. The {@code event} discriminator is fixed to
    50	     * {@link #EVENT_TYPE}.
    51	     */
    52	    public OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, Integer membershipLevel) {
    53	        this(seq, ownerId, customerCode, membershipLevel, EVENT_TYPE);
    54	    }
    55	
    56	    /**
    57	     * Renders this event as a compact JSON object with fields in declaration order:
    58	     * {@code {"seq":..,"ownerId":..,"customerCode":..,"membershipLevel":..,"event":"OWNER_CREATED"}}.
    59	     */
    60	    public String toJson() {
    61	        return MAPPER.writeValueAsString(this);
    62	    }
    63	}

