238	            }
239	        }
240	        normalizeAddress(ownerFieldsDto);
241	        validateRequiredFields(ownerFieldsDto);
242	        normalizeTelephone(ownerFieldsDto);
243	        normalizeEmail(ownerFieldsDto);
244	        validatePostcode(ownerFieldsDto);
245	        String householdId = computeHouseholdId(ownerFieldsDto);
246	        rejectDuplicate(ownerFieldsDto);
247	        rejectCityAtCapacity(ownerFieldsDto);
248	        resolveRegistrationDate(ownerFieldsDto);
249	        rejectDailyLimitReached(ownerFieldsDto.getRegistrationDate());
250	        HttpHeaders headers = new HttpHeaders();
251	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
252	        owner.setHouseholdId(householdId);
253	        assignCustomerCode(owner);
254	        assignMembershipNumber(owner);
255	        assignNamesakeCount(owner);
256	        assignBulkSignupWarning(owner);
257	        assignCapacityWarning(owner);
258	        assignPossibleDuplicate(owner, ownerFieldsDto);
259	        assignHouseholdMembership(owner);
260	        assignMembership(owner);
261	        this.clinicService.saveOwner(owner);
262	        if (idempotencyKey != null) {
263	            this.idempotentCreates.put(idempotencyKey, owner.getId());
264	        }
265	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
266	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
267	            owner.getMembershipNumber());
268	        emitOwnerCreatedEvent(owner);
269	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
270	        headers.setLocation(UriComponentsBuilder.newInstance()
271	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
272	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
273	    }
