438	    /**
439	     * Normalizes an owner's address on create, supporting both the structured form
440	     * ({@code addressLine1} plus optional {@code addressLine2}) and the flat {@code address} form kept
441	     * for backward compatibility. Whichever fields are supplied are canonicalized in place - trimmed,
442	     * internal whitespace runs collapsed to a single space, upper-cased and common street-type
443	     * abbreviations expanded as whole tokens ({@code ST}->{@code STREET}, {@code RD}->{@code ROAD},
444	     * {@code AVE}->{@code AVENUE}). The canonical {@code addressLine1}/{@code addressLine2} are written
445	     * back, and the composed {@code address} - the normalized {@code addressLine1} with a single space
446	     * and the normalized {@code addressLine2} appended when present, falling back to the normalized
447	     * flat {@code address} when no structured line is given - is written onto the request so it is what
448	     * gets validated, compared, stored and returned. Running before the required-field check means an
449	     * address that is blank in both forms after normalization is rejected like a missing one.
450	     */
451	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
452	        String line1 = canonicalAddress(ownerFieldsDto.getAddressLine1());
453	        String line2 = canonicalAddress(ownerFieldsDto.getAddressLine2());
454	        String flat = canonicalAddress(ownerFieldsDto.getAddress());
455	        ownerFieldsDto.setAddressLine1(line1);
456	        ownerFieldsDto.setAddressLine2(line2);
457	        ownerFieldsDto.setAddress(composeAddress(line1, line2, flat));
458	    }
459	
460	    /**
461	     * Composes the effective address, preferring the structured form: when {@code line1} is present
462	     * (non-blank) the result is {@code line1}, with a single space and {@code line2} appended when
463	     * {@code line2} is present; otherwise the flat {@code address} is used. All three inputs are
464	     * expected to be already canonicalized. Returns the flat value (which may be {@code null} or blank,
465	     * left for the required-field check to reject) when no structured line is supplied.
466	     */
467	    private static String composeAddress(String line1, String line2, String flat) {
468	        if (line1 != null && !line1.isBlank()) {
469	            if (line2 != null && !line2.isBlank()) {
470	                return line1 + " " + line2;
471	            }
472	            return line1;
473	        }
474	        return flat;
475	    }
476	
477	    /**
478	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
479	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
480	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
481	     * address is returned unchanged, making it safe to apply to stored values during comparison.
482	     */
483	    private static String canonicalAddress(String address) {
484	        if (address == null) {
485	            return null;
486	        }
487	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
488	        if (collapsed.isEmpty()) {
489	            return "";
490	        }
491	        String[] tokens = collapsed.split(" ");
492	        StringBuilder sb = new StringBuilder(collapsed.length());
493	        for (int i = 0; i < tokens.length; i++) {
494	            if (i > 0) {
495	                sb.append(' ');
496	            }
497	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
498	        }
499	        return sb.toString();
500	    }
