502	    /**
503	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
504	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
505	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
506	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}, and when the
507	     * country code is one whose national-number length is known ({@code '+61'} => 9 national digits,
508	     * {@code '+1'} => 10) the national number must have exactly that many digits. The E.164 string is
509	     * written back onto the request so it is what gets stored and returned. Any value that cannot
510	     * form a valid E.164 number is rejected with a 400 response whose {@code errors} array names
511	     * {@code telephone}.
512	     */
513	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
514	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
515	    }
516	
517	    /**
518	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
519	     * (400) naming {@code telephone} when it cannot form a valid number.
520	     */
521	    private static String toE164(String telephone) {
522	        if (telephone == null) {
523	            throw new InvalidOwnerFieldsException(List.of("telephone"));
524	        }
525	        boolean hasCountryCode = telephone.trim().startsWith("+");
526	        String digits = telephone.replaceAll("\\D", "");
527	        String countryCode;
528	        String national;
529	        if (hasCountryCode) {
530	            countryCode = matchCountryCode(digits);
531	            national = digits;
532	        } else {
533	            countryCode = "61";
534	            if (digits.startsWith("0")) {
535	                digits = digits.substring(1);
536	            }
537	            national = "61" + digits;
538	        }
539	        if (!national.matches("[0-9]{8,15}")) {
540	            throw new InvalidOwnerFieldsException(List.of("telephone"));
541	        }
542	        if (countryCode != null) {
543	            Integer requiredLength = COUNTRY_NATIONAL_LENGTH.get(countryCode);
544	            if (requiredLength != null
545	                && national.length() - countryCode.length() != requiredLength) {
546	                throw new InvalidOwnerFieldsException(List.of("telephone"));
547	            }
548	        }
549	        return "+" + national;
550	    }
551	
552	    /**
553	     * Returns the longest known E.164 country code (a key of {@link #COUNTRY_NATIONAL_LENGTH}) that
554	     * the given country-code-prefixed digit string starts with, or {@code null} when none is known so
555	     * the number is not length-checked against a country.
556	     */
557	    private static String matchCountryCode(String digits) {
558	        return COUNTRY_NATIONAL_LENGTH.keySet().stream()
559	            .filter(digits::startsWith)
560	            .max(Comparator.comparingInt(String::length))
561	            .orElse(null);
562	    }
