564	    /**
565	     * Rejects creating an owner that duplicates an existing one on the derived {@code identityKey} -
566	     * the SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' +
567	     * soundex(lastName)} (see {@link IdentityKey}). An exact key match means the same telephone, email
568	     * and same-sounding surname, i.e. the same person re-registering; because the telephone is part of
569	     * the key, two people who merely share a surname (and postcode) but carry different telephones no
570	     * longer collide here - they are surfaced as a soft match instead (see
571	     * {@link #assignPossibleDuplicate}). This single identity key is the only hard-duplicate rule; the
572	     * computed {@code householdId} no longer contributes a separate 409. A match is a 409.
573	     *
574	     * <p>Owners flagged {@code deleted} (soft-deleted via {@code DELETE /api/owners/{id}}) are skipped
575	     * entirely, so a normally-blocking duplicate is allowed when the only matching owner has been
576	     * deleted.
577	     *
578	     * <p>The {@code sharesHousehold} flag bypasses the entire duplicate block. The incoming telephone
579	     * and email have already been normalized by {@link #normalizeTelephone} and {@link #normalizeEmail}
580	     * (the email-domain blocklist applies first, in {@link #normalizeEmail}); each existing owner's key
581	     * is derived the same way before comparison. A match results in a 409 response naming
582	     * {@code identityKey}.
583	     */
584	    private void rejectDuplicate(OwnerFieldsDto ownerFieldsDto) {
585	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
586	            return;
587	        }
588	        String identityKey = IdentityKey.of(ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail(),
589	            ownerFieldsDto.getLastName());
590	        for (Owner existing : this.clinicService.findAllOwners()) {
591	            if (Boolean.TRUE.equals(existing.getDeleted())) {
592	                continue;
593	            }
594	            if (identityKey.equals(existingIdentityKey(existing))) {
595	                throw new DuplicateOwnerIdentityException(identityKey);
596	            }
597	        }
598	    }
599	
600	    /**
601	     * Derives an already-stored owner's {@code identityKey} for duplicate comparison: the stored
602	     * telephone is converted to E.164 form (or the empty string when it cannot form a valid number),
603	     * the stored email is lower-cased and the stored last name is reduced to its Soundex code, exactly
604	     * as {@link IdentityKey#of} does for an incoming request.
605	     */
606	    private static String existingIdentityKey(Owner existing) {
607	        String telephone = orEmpty(normalizeExisting(existing.getTelephone()));
608	        return IdentityKey.of(telephone, existing.getEmail(), existing.getLastName());
609	    }
610	
611	    private static String orEmpty(String value) {
612	        return value == null ? "" : value;
613	    }
614	
615	    /**
616	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
617	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
618	     */
619	    private static String normalizeExisting(String telephone) {
620	        try {
621	            return toE164(telephone);
622	        } catch (InvalidOwnerFieldsException ex) {
623	            return null;
624	        }
625	    }
626	
627	    /**
628	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
629	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
630	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
631	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
632	     */
633	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
634	        String city = ownerFieldsDto.getCity();
635	        int count = 0;
636	        for (Owner existing : this.clinicService.findAllOwners()) {
637	            if (city.equalsIgnoreCase(existing.getCity())) {
638	                count++;
639	            }
640	        }
641	        if (count >= MAX_OWNERS_PER_CITY) {
642	            throw new OwnerCityAtCapacityException(city);
643	        }
644	    }
645	
646	    /**
647	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
648	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
649	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
650	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
651	     */
652	    private void rejectDailyLimitReached(LocalDate registrationDate) {
653	        int count = 0;
654	        for (Owner existing : this.clinicService.findAllOwners()) {
655	            if (registrationDate.equals(existing.getRegistrationDate())) {
656	                count++;
657	            }
658	        }
659	        if (count >= MAX_OWNERS_PER_DAY) {
660	            throw new DailyOwnerLimitReachedException(registrationDate);
661	        }
662	    }
663	
664	    /**
665	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
666	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
667	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
668	     */
669	    private static String normalizeForComparison(String value) {
670	        if (value == null) {
671	            return "";
672	        }
673	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
674	    }
675	
676	    /**
677	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
678	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
679	     * written back onto the request so that is what gets stored and returned. A present but invalid
680	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
681	     */
682	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
683	        String email = ownerFieldsDto.getEmail();
684	        if (email == null) {
685	            return;
686	        }
687	        String trimmed = email.trim();
688	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
689	            throw new InvalidOwnerFieldsException(List.of("email"));
690	        }
691	        String normalized = trimmed.toLowerCase(Locale.ROOT);
692	        String domain = normalized.substring(normalized.indexOf('@') + 1);
693	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
694	            throw new InvalidOwnerFieldsException(List.of("email"));
695	        }
696	        ownerFieldsDto.setEmail(normalized);
697	    }
698	
699	    /**
700	     * Validates an owner's optional {@code postcode} on create. The field may be omitted entirely
701	     * (so an owner created without a postcode stays accepted), but when a value is present it must be
702	     * exactly 4 digits and valid for the region the owner's {@code city} derives to: NSW 2000-2099,
703	     * VIC 3000-3099, QLD 4000-4099. A city with no known region accepts any 4-digit postcode. A
704	     * present postcode that is malformed or out of range for the city's region is rejected with a 400
705	     * response whose {@code errors} array names {@code postcode}. A valid value is left on the request
706	     * as-is so it is stored and returned.
707	     */
708	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
709	        String postcode = ownerFieldsDto.getPostcode();
710	        if (postcode == null) {
711	            return;
712	        }
713	        if (!postcode.matches("[0-9]{4}")) {
714	            throw new InvalidOwnerFieldsException(List.of("postcode"));
715	        }
716	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.derive(ownerFieldsDto.getCity()));
717	        if (range != null) {
718	            int value = Integer.parseInt(postcode);
719	            if (value < range[0] || value > range[1]) {
720	                throw new InvalidOwnerFieldsException(List.of("postcode"));
721	            }
722	        }
723	    }
724	
725	    /**
726	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
727	     * day. When the caller supplies no value it defaults to the server's current date; a value
728	     * provided in the request is kept. A supplied value later than the server's current date is
729	     * rejected with a 400 response whose {@code errors} array names {@code registrationDate}. The
730	     * effective date, whether supplied or defaulted, must fall on a business day: a Saturday or
731	     * Sunday is rolled forward to the following Monday. The adjusted date is written back onto the
732	     * request so it is what gets stored and returned (in ISO {@code YYYY-MM-DD} format) and what
733	     * every value derived from the registration date is based on.
734	     */
735	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
736	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
737	        if (effective == null) {
738	            effective = LocalDate.now();
739	        }
740	        else if (effective.isAfter(LocalDate.now())) {
741	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
742	        }
743	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
744	    }
745	
746	    /**
747	     * The fixed public-holiday calendar. A registration date landing on one of these days is rolled
748	     * forward, just like a weekend, until it reaches a non-holiday business day.
749	     */
750	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
751	        LocalDate.of(2026, 1, 1),
752	        LocalDate.of(2026, 1, 26),
753	        LocalDate.of(2026, 4, 25),
754	        LocalDate.of(2026, 12, 25),
755	        LocalDate.of(2026, 12, 28));
756	
757	    /**
758	     * Rolls a date forward onto a business day: a Saturday, Sunday or listed public holiday is
759	     * advanced one day at a time until it reaches the next non-holiday business day; a weekday that
760	     * is not a holiday is returned unchanged.
761	     */
762	    private static LocalDate toBusinessDay(LocalDate date) {
763	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
764	            date = date.plusDays(1);
765	        }
766	        return date;
767	    }
768	
769	    /**
770	     * Returns whether the given date falls on a Saturday or Sunday.
771	     */
772	    private static boolean isWeekend(LocalDate date) {
773	        return switch (date.getDayOfWeek()) {
774	            case SATURDAY, SUNDAY -> true;
775	            default -> false;
776	        };
777	    }
778	
779	    /**
780	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
781	     * {@code REGION} is the region the owner's identity derives to from its postcode (falling back to
782	     * the city table when the postcode is absent or in no known range) and {@code HASH8} is the first
783	     * eight upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
784	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The telephone has already been normalized to
785	     * E.164 form by {@link #normalizeTelephone}. There is no per-city sequence: the identity is a
786	     * pure function of region, telephone and last name.
787	     */
788	    private void assignCustomerCode(Owner owner) {
789	        String region = OwnerLocality.derive(owner.getCity(), owner.getPostcode());
790	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName(), 8);
791	        owner.setCustomerCode(deduplicateCustomerCode(region + "-" + hash8));
792	    }
793	
794	    /**
795	     * Returns {@code customerCode} unchanged when no existing owner already carries it; otherwise
796	     * appends {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not held by
797	     * any existing owner. Compared against the pre-existing owners, so the returned code is unique
798	     * among them.
799	     */
800	    private String deduplicateCustomerCode(String customerCode) {
801	        Set<String> existing = new HashSet<>();
802	        for (Owner owner : this.clinicService.findAllOwners()) {
803	            if (owner.getCustomerCode() != null) {
804	                existing.add(owner.getCustomerCode());
805	            }
806	        }
807	        if (!existing.contains(customerCode)) {
808	            return customerCode;
809	        }
810	        int n = 2;
811	        while (existing.contains(customerCode + "-" + n)) {
812	            n++;
813	        }
814	        return customerCode + "-" + n;
815	    }
816	
817	    /**
818	     * Assigns the owner's {@code membershipNumber} on create, formatted
819	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the fiscal year of
820	     * the business-day-adjusted {@code registrationDate} (the fiscal year starts on 1 July, e.g. a
821	     * registration on 2026-08-03 falls in fiscal year 2027 and yields {@code 'NSW-1A2B3C4D-M27'}).
822	     * Assigned after {@link #assignCustomerCode} and once {@code registrationDate} has been
823	     * defaulted, so both inputs are present.
824	     */
825	    private void assignMembershipNumber(Owner owner) {
826	        String yy = String.format("%02d", FiscalYear.yearOf(owner.getRegistrationDate()) % 100);
827	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
828	    }
829	
830	    /**
831	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
832	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
833	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
834	     */
835	    private void assignNamesakeCount(Owner owner) {
836	        String firstName = owner.getFirstName();
837	        String lastName = owner.getLastName();
838	        int count = 0;
839	        for (Owner existing : this.clinicService.findAllOwners()) {
840	            if (firstName.equalsIgnoreCase(existing.getFirstName())
841	                && lastName.equalsIgnoreCase(existing.getLastName())) {
842	                count++;
843	            }
844	        }
845	        owner.setNamesakeCount(count);
846	    }
847	
848	    /**
849	     * Assigns the new owner's {@code membershipPoints} and derived {@code membershipLevel} on create.
850	     * Points start at 0 and accrue: plus 2 when an email is present, plus 1 when {@code namesakeCount}
851	     * is 0, plus 2 for a household of 3 or more members, and plus 3 for tenure exceeding
852	     * {@value #TENURE_LEVEL_THRESHOLD_FISCAL_YEARS} elapsed fiscal year. The points are then mapped to a level of 1 (0-1
853	     * points), 2 (2-3), 3 (4-5), or 4 (6 or more). Runs after {@link #assignNamesakeCount} and
854	     * {@link #assignHouseholdMembership} so those counts are settled. A newly created owner has zero
855	     * tenure, so the tenure bonus never applies on create.
856	     */
857	    private void assignMembership(Owner owner) {
858	        int points = 0;
859	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
860	            points += 2;
861	        }
862	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
863	            points += 1;
864	        }
865	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
866	            points += 2;
867	        }
868	        if (tenureFiscalYears(owner) > TENURE_LEVEL_THRESHOLD_FISCAL_YEARS) {
869	            points += 3;
870	        }
871	        owner.setMembershipPoints(points);
872	        owner.setMembershipLevel(capMembershipLevelByHousehold(owner, membershipLevelForPoints(points)));
873	    }
874	
875	    /**
876	     * Caps a newly derived {@code membershipLevel} so it cannot exceed one above the current maximum
877	     * {@code membershipLevel} among the new owner's existing household members - the pre-existing owners
878	     * already carrying the same {@code householdId}. When the owner belongs to no household, or has no
879	     * existing household member, no cap applies and the derived level is returned unchanged. Runs after
880	     * {@link #assignHouseholdMembership} so the owner's {@code householdId} is settled.
881	     */
882	    private int capMembershipLevelByHousehold(Owner owner, int derivedLevel) {
883	        String householdId = owner.getHouseholdId();
884	        if (householdId == null || householdId.isBlank()) {
885	            return derivedLevel;
886	        }
887	        Integer maxHouseholdLevel = null;
888	        for (Owner existing : this.clinicService.findAllOwners()) {
889	            if (householdId.equals(existing.getHouseholdId()) && existing.getMembershipLevel() != null
890	                && (maxHouseholdLevel == null || existing.getMembershipLevel() > maxHouseholdLevel)) {
891	                maxHouseholdLevel = existing.getMembershipLevel();
892	            }
893	        }
894	        if (maxHouseholdLevel == null) {
895	            return derivedLevel;
896	        }
897	        return Math.min(derivedLevel, maxHouseholdLevel + 1);
898	    }
899	
900	    /**
901	     * Maps {@code membershipPoints} to a {@code membershipLevel}: 1 for 0-1 points, 2 for 2-3, 3 for
902	     * 4-5, and 4 for 6 or more points.
903	     */
904	    private int membershipLevelForPoints(int points) {
905	        if (points <= 1) {
906	            return 1;
907	        }
908	        if (points <= 3) {
909	            return 2;
910	        }
911	        if (points <= 5) {
912	            return 3;
913	        }
914	        return 4;
915	    }
916	
917	    /**
918	     * The tenure, in elapsed fiscal years, of a newly created owner. Tenure accrues from membership
919	     * over time, and a new owner has not been a member for any elapsed fiscal year yet, so this is
920	     * always {@code 0} on create (regardless of any backdated {@code registrationDate}).
921	     */
922	    private long tenureFiscalYears(Owner owner) {
923	        return 0L;
924	    }
925	
926	    /**
927	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
928	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
929	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
930	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
931	     * pre-existing owners for that day.
932	     */
933	    private void assignBulkSignupWarning(Owner owner) {
934	        LocalDate registrationDate = owner.getRegistrationDate();
935	        int count = 0;
936	        for (Owner existing : this.clinicService.findAllOwners()) {
937	            if (registrationDate.equals(existing.getRegistrationDate())) {
938	                count++;
939	            }
940	        }
941	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
942	    }
943	
944	    /**
945	     * Assigns the new owner's {@code capacityWarning} on create: {@code true} when the owner's city
946	     * already holds between {@value #CAPACITY_WARNING_THRESHOLD} and {@value #MAX_OWNERS_PER_CITY}
947	     * minus one owners (approaching the {@value #MAX_OWNERS_PER_CITY} capacity limit), otherwise
948	     * {@code false}. Existing owners are counted case-insensitively on {@code city}, the same way
949	     * {@link #rejectCityAtCapacity} counts them, and computed before the new owner is persisted so it
950	     * counts only the pre-existing owners. A city at or over the hard limit has already been rejected
951	     * by {@link #rejectCityAtCapacity}, so this only ever sees counts below the limit.
952	     */
953	    private void assignCapacityWarning(Owner owner) {
954	        String city = owner.getCity();
955	        int count = 0;
956	        for (Owner existing : this.clinicService.findAllOwners()) {
957	            if (city.equalsIgnoreCase(existing.getCity())) {
958	                count++;
959	            }
960	        }
961	        owner.setCapacityWarning(count >= CAPACITY_WARNING_THRESHOLD && count < MAX_OWNERS_PER_CITY);
962	    }
963	
964	    /**
965	     * Assigns the new owner's {@code possibleDuplicate} / {@code possibleDuplicateOf} on create. The
966	     * owner has already cleared the duplicate block, so it is not a hard duplicate. It is flagged as a
967	     * possible duplicate when an existing owner has the same {@code soundex(lastName)} and the same
968	     * {@code postcode} (a present, exact match) yet a <em>different</em> {@code identityKey} - the
969	     * soft-match now keys on the surname sound and postcode rather than an exact last name, and fires
970	     * precisely for the near-miss the identity key lets through (same household surname and postcode
971	     * but a different telephone, so a different key). When such an owner exists,
972	     * {@code possibleDuplicate} is set to {@code true} and {@code possibleDuplicateOf} to that owner's
973	     * id (the lowest id when several match); otherwise {@code possibleDuplicate} is {@code false} and
974	     * {@code possibleDuplicateOf} is left {@code null}. Computed before the new owner is persisted, so
975	     * it considers only the pre-existing owners.
976	     *
977	     * <p>A declared household member ({@code sharesHousehold} set to {@code true}) is never flagged: it
978	     * has deliberately opted into an existing household, so its shared last name and postcode are
979	     * expected rather than a suspected duplicate.
980	     */
981	    private void assignPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
982	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
983	            owner.setPossibleDuplicate(false);
984	            owner.setPossibleDuplicateOf(null);
985	            return;
986	        }
987	        String postcode = owner.getPostcode();
988	        String soundex = IdentityKey.soundex(owner.getLastName());
989	        String identityKey = IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
990	        Integer matchId = null;
991	        if (postcode != null && !postcode.isBlank()) {
992	            for (Owner existing : this.clinicService.findAllOwners()) {
993	                if (soundex.equals(IdentityKey.soundex(existing.getLastName()))
994	                    && postcode.equals(existing.getPostcode())
995	                    && !identityKey.equals(existingIdentityKey(existing))
996	                    && existing.getId() != null
997	                    && (matchId == null || existing.getId() < matchId)) {
998	                    matchId = existing.getId();
999	                }
1000	            }
1001	        }
1002	        owner.setPossibleDuplicate(matchId != null);
1003	        owner.setPossibleDuplicateOf(matchId);
1004	    }
1005	
1006	    /**
1007	     * Computes the new owner's deterministic {@code householdId}: the first twelve upper-case hex
1008	     * characters of the SHA-256 digest of {@code "<normalizedLastName>|<postcode>"}, where the last
1009	     * name is normalized for comparison (trimmed, internal whitespace collapsed, lower-cased) and the
1010	     * postcode is the already-validated 4-digit value. Because it is a pure function of the last name
1011	     * and postcode, any two owners sharing those - regardless of creation order or whether they opted
1012	     * into {@code sharesHousehold} - land in the same household automatically. Returns {@code null}
1013	     * when the owner has no postcode, so such owners belong to no household. This single value feeds
1014	     * both the duplicate detection ({@link #rejectDuplicate}) and the household-size count
1015	     * ({@link #assignHouseholdMembership}).
1016	     */
1017	    private String computeHouseholdId(OwnerFieldsDto ownerFieldsDto) {
1018	        String postcode = ownerFieldsDto.getPostcode();
1019	        if (postcode == null || postcode.isBlank()) {
1020	            return null;
1021	        }
1022	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
1023	        return shaHexUpper(lastName + "|" + postcode, 12);
1024	    }
1025	
1026	    /**
1027	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
1028	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
1029	     * every existing owner already carrying the same identifier. Runs after the owner's
1030	     * {@code householdId} has been set from {@link #computeHouseholdId} so the identifier is settled.
1031	     * Left {@code null} when the owner belongs to no household.
1032	     */
1033	    private void assignHouseholdMembership(Owner owner) {
1034	        String householdId = owner.getHouseholdId();
1035	        if (householdId == null || householdId.isBlank()) {
1036	            owner.setHouseholdMemberCount(null);
1037	            return;
1038	        }
1039	        int count = 1;
1040	        for (Owner existing : this.clinicService.findAllOwners()) {
1041	            if (householdId.equals(existing.getHouseholdId())) {
1042	                count++;
1043	            }
1044	        }
1045	        owner.setHouseholdMemberCount(count);
1046	    }
1047	
1048	    /**
1049	     * Returns the first {@code length} characters of the SHA-256 digest of {@code input}, rendered as
1050	     * upper-case hexadecimal. Used to derive the {@code customerCode} hash segment and the household
1051	     * identifier, both stable functions of their inputs.
1052	     */
1053	    private static String shaHexUpper(String input, int length) {
1054	        try {
1055	            byte[] digest = MessageDigest.getInstance("SHA-256")
1056	                .digest(input.getBytes(StandardCharsets.UTF_8));
1057	            StringBuilder hex = new StringBuilder(digest.length * 2);
1058	            for (byte b : digest) {
1059	                hex.append(String.format("%02x", b));
1060	            }
1061	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
1062	        } catch (NoSuchAlgorithmException ex) {
1063	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
1064	        }
1065	    }
1066	}
